//! Build-time codegen for `spawns_obj.json`: dump order kept. A null row
//! renders `obj: -1`, which the caller skips exactly like the old reader.

/// Render `spawns_obj_generated.rs` from the parsed dump.
pub fn generate(manifest_dir: &str) {
    let parsed = crate::parse_dump(manifest_dir, "spawns_obj");
    let rows = crate::dump_rows(&parsed, "spawns_obj");
    let mut generated = String::from(
        "// Generated by rs/crates/gamedata/build.rs from gamedata/data/spawns_obj.json - do not edit.\n\
         pub static ALL: &[super::StaticObjSpawn] = &[\n",
    );
    for row in rows {
        generated.push_str(&format!(
            "    super::StaticObjSpawn {{ level: {}, x: {}, z: {}, obj: {}, count: {}, members: {} }},\n",
            row.get("level").as_i64().unwrap_or(0),
            row.get("x").as_i64().unwrap_or(0),
            row.get("z").as_i64().unwrap_or(0),
            row.get("obj").as_i64().unwrap_or(-1),
            row.get("count").as_i64().unwrap_or(1),
            crate::render_opt_flag(row, "members"),
        ));
    }
    generated.push_str("];\n");
    crate::emit_generated("spawns_obj_generated.rs", &generated);
}
